export function getMatchesByDate(date: string): Match[] {
  return schedule.filter(m => m.date === date);
}

export function getMatchesByGroup(groupId: string): Match[] {
  return schedule.filter(m => m.group === groupId);
}

export function getMatchById(id: string): Match | undefined {
  return schedule.find(m => m.id === id);
}
